9	export default async function sitemap(): Promise<MetadataRoute.Sitemap> {
10	  const now = new Date();
11	
12	  const staticRoutes: Array<{ path: string; priority: number; freq: MetadataRoute.Sitemap[number]["changeFrequency"] }> = [
13	    { path: "", priority: 1.0, freq: "weekly" },
14	    { path: "/features", priority: 0.8, freq: "monthly" },
15	    { path: "/vibe-coding", priority: 0.8, freq: "monthly" },
16	    { path: "/pricing", priority: 0.9, freq: "weekly" },
17	    { path: "/vps", priority: 0.8, freq: "monthly" },
18	    { path: "/domains", priority: 0.8, freq: "monthly" },
19	    { path: "/compare", priority: 0.7, freq: "monthly" },
20	    { path: "/vps-vs-digitalocean", priority: 0.7, freq: "monthly" },
21	    { path: "/vps-vs-hostinger", priority: 0.7, freq: "monthly" },
22	    { path: "/about", priority: 0.5, freq: "monthly" },
23	    { path: "/contact", priority: 0.5, freq: "monthly" },
24	    { path: "/blog", priority: 0.7, freq: "weekly" },
25	    { path: "/tools", priority: 0.7, freq: "weekly" },
26	    ...TOOL_SLUGS.map((slug) => ({
27	      path: `/tools/${slug}`,
28	      priority: 0.6,
29	      freq: "monthly" as const,
30	    })),
31	    { path: "/status", priority: 0.4, freq: "daily" },
32	    { path: "/legal/terms", priority: 0.3, freq: "yearly" },
33	    { path: "/legal/privacy", priority: 0.3, freq: "yearly" },
34	    { path: "/legal/aup", priority: 0.3, freq: "yearly" },
35	    { path: "/legal/sla", priority: 0.3, freq: "yearly" },
36	  ];
37	
38	  const entries: MetadataRoute.Sitemap = staticRoutes.map((r) => ({
39	    url: `${APP_URL}${r.path}`,
40	    lastModified: now,
41	    changeFrequency: r.freq,
42	    priority: r.priority,
43	  }));
44	
45	  // Published blog posts (model may not be migrated yet — access defensively).
46	  try {
47	    const blogModel = (db as unknown as { blogPost?: { findMany: (a: unknown) => Promise<Array<{ slug: string; updatedAt: Date }>> } }).blogPost;
48	    const posts = blogModel
49	      ? await blogModel.findMany({
50	          where: { published: true },
51	          select: { slug: true, updatedAt: true },
52	          orderBy: { publishedAt: "desc" },
53	        })
54	      : [];
55	    for (const p of posts) {
56	      entries.push({
57	        url: `${APP_URL}/blog/${p.slug}`,
58	        lastModified: p.updatedAt,
59	        changeFrequency: "monthly",
60	        priority: 0.6,
61	      });
62	    }
63	  } catch {
64	    // blogPost model not migrated yet — skip.
65	  }
66	
67	  return entries;
68	}
