5	/** Format a remaining-milliseconds span as "2d 4h 10m" / "4h 10m 5s" / "10m 5s". */
6	function fmt(ms: number): string {
7	  const totalSec = Math.max(0, Math.floor(ms / 1000));
8	  const d = Math.floor(totalSec / 86400);
9	  const h = Math.floor((totalSec % 86400) / 3600);
10	  const m = Math.floor((totalSec % 3600) / 60);
11	  const s = totalSec % 60;
12	  const parts: string[] = [];
13	  if (d) parts.push(`${d}d`);
14	  if (d || h) parts.push(`${h}h`);
15	  parts.push(`${m}m`);
16	  if (!d) parts.push(`${s}s`); // seconds only matter once we're inside a day
17	  return parts.join(" ");
18	}
