20	/**
21	 * Live promo countdown. `endsAt` is the real ISO close date of the active promo
22	 * (from promoEndsAt). Ticks every second; shows a stable placeholder before the
23	 * client mounts to avoid hydration mismatch.
24	 */
25	export function PromoCountdown({
26	  endsAt,
27	  prefix = "ends in",
28	  className = "",
29	}: {
30	  endsAt: string;
31	  prefix?: string;
32	  className?: string;
33	}) {
34	  const end = Date.parse(endsAt);
35	  const [remaining, setRemaining] = useState<number | null>(null);
36	
37	  useEffect(() => {
38	    const tick = () => setRemaining(end - Date.now());
39	    tick();
40	    const t = setInterval(tick, 1000);
41	    return () => clearInterval(t);
42	  }, [end]);
43	
44	  if (remaining === null) {
45	    return (
46	      <span className={className} suppressHydrationWarning>
47	        {prefix} …
48	      </span>
49	    );
50	  }
51	  if (remaining <= 0) {
52	    // Promos rotate by calendar date; the next one is taking over.
53	    return <span className={className}>Refreshing…</span>;
54	  }
55	  return (
56	    <span className={className} suppressHydrationWarning>
57	      {prefix} {fmt(remaining)}
58	    </span>
59	  );
60	}
